$string['settings:socratic_verbose_desc'] = 'Când este activată, cursurile în mod socratic primesc directiva completă de ~600 de jetoane cu ce să facă și ce să nu facă, adăugată inițial în v3.9.30. Când este dezactivată (implicit), acestea primesc o directivă pe un singur rând, pe care modelele găzduite moderne o urmează în mod fiabil și care economisește ~600 de jetoane pe tură. Activați-o dacă un curs rulează pe un model auto-găzduit mai slab, care are nevoie de schele explicite.';
$string['settings:prompt_budget_chars'] = 'Bugetul de caractere al promptului de sistem';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'Limita conținutului paginii curente (caractere)';
$string['settings:current_page_content_maxchars_desc'] = 'Numărul maxim de caractere din textul paginii curente injectate în promptul de sistem ca secțiunea "Current Page Content", când RAG este dezactivat. Valoarea implicită de 8,000 fundamentează bine întrebările specifice paginii, lăsând totodată buget pentru structură și instrucțiuni. (Cu RAG activat, pagina este în schimb fundamentată prin propriile fragmente cele mai relevante, cu preferință pentru pagina curentă, deci această limită nu se aplică.) O pagină foarte lungă este trunchiată de la început până la acest număr de caractere, astfel încât finalul unei pagini extrem de lungi ar putea să nu fie citat; activarea RAG evită acest lucru. Site-urile atente la costuri pot limita această valoare mai jos (de ex. 3,000-4,000). Limitat la intervalul 500-8,000. Independent de <code>prompt_budget_chars</code>: aceasta limitează doar secțiunea paginii; bugetul limitează întregul prompt.';
$string['settings:prompt_verbosity'] = 'Nivelul de detaliu al promptului';
$string['settings:prompt_verbosity_desc'] = 'Nivelul implicit de detaliu pentru blocurile de instrucțiuni (modul socratic, resurse externe). Concis (implicit) este ceea ce modelele găzduite moderne urmează în mod fiabil; standard adaugă schele explicite pentru modelele de nivel mediu; detaliat păstrează îndrumarea masivă din epoca v3.9.30 pentru modelele auto-găzduite mai slabe. Suprascriere per curs disponibilă prin <code>prompt_verbosity_course_&lt;id&gt;</code>.';
$string['settings:prompt_verbosity_concise'] = 'Concis (recomandat pentru modelele găzduite)';
$string['settings:prompt_verbosity_standard'] = 'Standard';
$string['settings:prompt_verbosity_verbose'] = 'Detaliat (pentru modele auto-găzduite mai slabe)';
$string['settings:prompt_metrics_enabled'] = 'Colectează metrici de prompt pe secțiuni';
$string['settings:prompt_metrics_enabled_desc'] = 'Când este activată (implicit), fiecare tură de chat scrie câte o linie JSON pentru fiecare prompt asamblat în <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code>, cu numărul de caractere pe categorie. Se păstrează ultimele 7 zile. Pagina de administrare a metricilor le agregă pentru recomandarea de buget. Nu se înregistrează date cu caracter personal — doar dimensiunile secțiunilor. Dezactivați-o dacă instituția dvs. preferă să nu existe deloc un fișier de metrici.';
$string['settings:prompt_budget_auto_tune'] = 'Ajustare automată zilnică a bugetului promptului de sistem (învechit)';
$string['settings:prompt_budget_auto_tune_desc'] = 'Învechit. Nu face nimic decât dacă modul de buget de mai sus este setat pe <strong>Fix</strong>. O sarcină zilnică deducea bugetul de caractere urmărind trunchierile și alergând după cel mai mare prompt pe care îl văzuse. Derivarea bugetului din fereastra de context a modelului face asta mai bine: nu poate oscila și nu are nevoie de date de pornire. Cele două intrau și în conflict, pentru că sarcina scrie bugetul de caractere, iar orice valoare diferită de cea implicită dezactivează bugetul derivat. Lasă asta dezactivat; va fi eliminat într-o versiune viitoare. Recomandarea apare în continuare pe pagina <a href="/local/ai_course_assistant/prompt_metrics.php">Metrici prompt</a>.';
$string['task:auto_tune_prompt_budget'] = 'Reglează automat bugetul de prompt al [[tutorshort]] pe baza metricilor observate';
