$string['empathy:memory_enabled'] = 'Activează memoria de personalizare de continuitate';
$string['empathy:memory_enabled_desc'] = 'Îi permite lui [[tutorshort]] să păstreze mici notițe private despre ce i-a fost greu unui cursant, de la o sesiune la alta, astfel încât răspunsul următor să poată propune o altă abordare. Limitată (maximum 5 notițe per cursant per curs, TTL de 90 de zile). Poate fi editată de cursant. Niciodată vizibilă pentru instructori.';
$string['empathy:struggle_enabled'] = 'Activează clasificatorul de dificultate';
