$string['settings:escalation_intent_patterns'] = 'Modele de intenție de escaladare';
$string['settings:escalation_intent_patterns_desc'] = 'PCRE, no delimiters. O expresie regulată pe linie; liniile care încep cu # sunt ignorate. Un tichet de asistență este deschis doar când mesajul propriu al cursantului se potrivește cu unul dintre aceste modele, astfel încât conținutul cursului să nu poată declanșa o escaladare în numele său. Lăsați gol pentru a folosi valorile implicite integrate, care acoperă engleza plus câteva formulări uzuale în spaniolă, franceză, germană și portugheză. Site-urile ai căror cursanți scriu în altă limbă ar trebui să adauge modele aici: un mesaj fără potrivire înseamnă că nu se deschide niciun tichet.';
$string['settings:zendesk_require_consent'] = 'Solicitați consimțământul înainte de escaladarea către suport';
$string['settings:zendesk_require_consent_desc'] = 'Când este activat (recomandat), [[tutorshort]] escaladează o conversație către biroul de suport Zendesk doar după ce cursantul a acceptat notificarea de consimțământ de la prima rulare, care dezvăluie că solicitarea de ajutor uman partajează conversația (inclusiv numele și e-mailul) cu suportul. Dezactivați acest lucru doar dacă obțineți acel consimțământ într-un alt mod; cu opțiunea dezactivată, escaladările sunt trimise imediat. Nu are efect decât dacă escaladarea Zendesk este activată.';
$string['chat:escalation_needs_consent'] = 'Se pare că acest lucru necesită un membru al echipei noastre de suport. Pentru a-l transmite lor, ar trebui să partajez această conversație, inclusiv numele și e-mailul dvs., cu biroul de suport. Nu ați fost încă de acord cu acest lucru, așa că nu am trimis nimic. Dacă doriți ajutor uman, vă rugăm să acceptați notificarea de partajare a datelor pentru acest asistent și să întrebați din nou, sau contactați direct suportul.';
$string['privacy:metadata:email_optout'] = 'Preferințele de renunțare la e-mail pe destinatar (la ce tipuri de e-mail s-a dezabonat un destinatar).';
$string['privacy:metadata:email_optout:email'] = 'Adresa de e-mail a destinatarului căreia i se aplică renunțarea.';
$string['privacy:metadata:email_optout:optout_type'] = 'Tipul de e-mail de la care s-a dezabonat destinatarul.';
$string['privacy:metadata:email_optout:userid'] = 'Utilizatorul Moodle căruia îi aparține renunțarea, când este cunoscut.';
$string['chat:consent_scroll_hint'] = 'Vă rugăm să derulați până jos pentru a citi notificarea completă înainte de a continua.';
$string['settings:rag_min_similarity'] = 'Relevanță minimă (cosinus)';
$string['settings:rag_min_similarity_desc'] = 'Renunță la fragmentele recuperate a căror similaritate cosinus față de întrebare este sub această valoare, astfel încât o întrebare în afara subiectului sau săracă în conținut să injecteze mai puține (sau zero) pasaje, în loc să completeze mereu până la Top-K cu potriviri slabe. Interval de la 0 la 1; 0 dezactivează filtrul. Valoarea potrivită depinde de modelul de embedding: 0.25 se potrivește pentru text-embedding-3-small. Mărește-o pentru a fi mai strict (mai puțin context, mai bine focalizat pe subiect), micșoreaz-o pentru a fi mai permisiv.';
$string['settings:rag_currentpage_boost'] = 'Bonus pentru pagina curentă';
$string['settings:rag_currentpage_boost_desc'] = 'Un mic bonus adăugat la scorul de relevanță al fragmentelor din pagina pe care cursantul o vizualizează în prezent, astfel încât întrebări precum "explică acest lucru" să prefere pagina vizibilă atunci când scorurile sunt apropiate. Doar ordonare: nu forțează trecerea unui fragment irelevant de pagină dincolo de filtrul de relevanță minimă. Setează 0 pentru a dezactiva.';
$string['settings:history_mode'] = 'Mod de selectare a istoricului';
$string['settings:history_mode_desc'] = 'Modul în care sunt alese tururile anterioare ale conversației înainte de a fi trimise modelului. <strong>Semantic</strong> păstrează doar tururile recente relevante pentru întrebarea curentă (și întotdeauna cel mai recent schimb), astfel încât un tur anterior învechit și în afara subiectului să nu umfle costul și să nu abată răspunsul de la subiect; face o apelare suplimentară de embedding per mesaj. <strong>Recență</strong> păstrează ultimele perechi "Max Conversation History" indiferent de relevanță (comportamentul de mult stabilit, fără apelare suplimentară). Dacă embedding-ul nu este disponibil, modul semantic revine automat la recență.';
$string['settings:history_mode_semantic'] = 'Semantic (tururi recente relevante)';
$string['settings:history_mode_recency'] = 'Recență (ultimele N perechi)';
$string['settings:history_semantic_minscore'] = 'Prag minim de relevanță a istoricului (cosinus)';
$string['settings:history_semantic_minscore_desc'] = 'În modul de istoric semantic, un tur anterior este păstrat doar dacă similaritatea sa față de întrebarea curentă este cel puțin această valoare (cel mai recent schimb este întotdeauna păstrat). Interval de la 0 la 1; depinde de model. Mărește pentru a fi mai strict (mai puțin istoric), micșorează pentru a păstra mai mult.';
$string['settings:history_candidates'] = 'Fereastra candidaților din istoric';
$string['settings:history_candidates_desc'] = 'În modul de istoric semantic, doar acest număr de cele mai recente perechi este evaluat pentru relevanță (o limită de cost). Perechile mai vechi decât această fereastră nu sunt trimise. Păstrează această valoare egală sau mai mare decât "Max Conversation History".';

