$string['settings:embed_provider_voyage'] = 'Voyage AI (voyage-3.5 — recomandat; +4 MTEB față de OpenAI 3-small, 4x context, multilingv)';
$string['settings:rerank_heading'] = 'RAG: Recuperare în două etape (re-ranking)';
$string['settings:rerank_heading_desc'] = 'A doua etapă opțională de recuperare: similaritatea cosinus selectează top-N fragmente candidate (implicit 50), apoi un cross-encoder re-ranker punctează fiecare pereche (interogare, fragment), iar cele mai bune top-K intră în prompt. Dezactivat implicit; revine la recuperarea cosinus cu o singură etapă dacă re-ranker-ul nu este configurat sau eșuează.';
$string['settings:rerank_enabled'] = 'Recuperare în două etape (Voyage rerank-2.5)';
