$string['settings:prompt_proportions_heading'] = 'Proporțiile secțiunilor de prompt (v5.6.0)';
$string['settings:prompt_proportions_heading_desc'] = 'Alocați bugetul prompt-ului de sistem pe patru segmente: siguranță + identitate, structura cursului, conținutul cursului și pagina curentă. Ponderile sunt procente care sumează la 100. Valorile implicite ajustate empiric (10 / 10 / 40 / 40) provin din benchmark-ul de ajustare a ponderilor v5.6.0; lăsând zona de text goală se utilizează acele valori implicite. Boost-ul automat ajustează alocarea per tur în funcție de dacă o anumită pagină este în domeniu.';
$string['settings:prompt_section_weights'] = 'Ponderi de secțiune de bază (JSON)';
$string['settings:prompt_section_weights_desc'] = 'Obiect JSON opțional care mapează fiecare segment la un procent. Lăsați necompletat pentru a utiliza valorile implicite din benchmark (10 / 10 / 40 / 40). Exemplu: <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>. Ponderile trebuie să sumeze la 100 (±5%). <code>safety_identity</code> are un minim de 10% pentru ca rezistența la jailbreak și marcatorii de format de ieșire să apară întotdeauna complet. <code>current_page + course_content</code> trebuie să fie cel puțin 40% pentru ca modelul să aibă material substanțial în care să se ancoreze. Valorile în afara intervalului revin în tăcere la valorile implicite din benchmark; administratorii ar trebui să valideze verificând jurnalul de depanare a prompt-ului după salvare.';
$string['settings:prompt_context_boost_mode'] = 'Mod de boost al contextului';
$string['settings:prompt_context_boost_mode_desc'] = 'Ajustare automată care deplasează ponderea spre secțiunea paginii curente când o anumită pagină este în domeniu și spre conținutul cursului când nicio pagină nu este selectată. <strong>page_focus</strong> (implicit) deplasează aproximativ 15 puncte de pondere. <strong>aggressive</strong> deplasează 25 de puncte și este cel mai bun când cursanții pun în mod constant întrebări specifice paginii. <strong>off</strong> dezactivează boost-ul; ponderile de bază setate de administrator se aplică la fiecare tur indiferent de contextul paginii.';
$string['settings:prompt_context_boost_off'] = 'Dezactivat (utilizați ponderile de bază la fiecare tur)';
$string['settings:prompt_context_boost_page_focus'] = 'Focus pe pagină (implicit, ~15 puncte de deplasare)';
$string['settings:prompt_context_boost_aggressive'] = 'Agresiv (~25 puncte de deplasare)';
$string['settings:prompt_section_weights_coach'] = 'Suprascriere în modul coach (JSON, opțional)';
$string['settings:prompt_section_weights_coach_desc'] = 'Obiect JSON opțional care suprascrie ponderile de secțiune de bază specific în timpul modului coach de quiz notat (când <code>quizmode=coach</code>). Util pentru a forța o alocare mai mare de <code>current_page</code> în timpul quiz-urilor fără a afecta chat-ul normal. Lăsați necompletat pentru a moșteni ponderile de bază. Aceleași reguli de validare ca și setarea de bază.';
